struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Precondition from the contract: len(question) <= 512. It holds of
        // every input by construction, so we rely on it rather than re-checking.

        // The only authority this node holds is inference (no tools, no I/O):
        // we can be *influenced* by the model's answer, but cannot act on it.
        let system = "\
You are a content-moderation classifier for customer-support queries. \
Read the user's question and reply with exactly one word on a single line:\n\
  ALLOW     - the question is acceptable and may proceed.\n\
  VIOLATION - the question violates policy (abuse, illegal, disallowed content).\n\
  ESCALATE  - the question needs a human (threats of harm, crisis, legal/safety).\n\
Reply with only that one word and nothing else.";

        let raw = crate::aap::caps::inference_llm::infer(system, &query.question, "moderate");
        let verdict = raw.trim().to_ascii_uppercase();

        // Match on the leading token so trailing commentary cannot change the
        // routing decision. Default is ALLOW only when the model clearly allows;
        // anything unrecognised is treated conservatively as an escalation.
        if verdict.starts_with("VIOLATION") {
            ModerationResult::Violation(PolicyViolation { reason: raw })
        } else if verdict.starts_with("ESCALATE") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: raw,
            })
        } else if verdict.starts_with("ALLOW") {
            ModerationResult::Ok(ModeratedQuery { query })
        } else {
            // Unparseable verdict: fail safe to a human rather than silently allow.
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "moderation verdict was not recognised".to_string(),
            })
        }
    }
}

export!(Node);
```

